        { 0, 0, 5, 5, 5, null, 10, AtmStatus.InsufficientFunds },
        { 250, 0, 1, 0, 0, Denomination.Fifty, 50, AtmStatus.CannotDispense },
        { 250, 0, 5, 5, 0, null, 30 + 0 * 1, AtmStatus.Ok }, // témoin : 20+10 impossible, mais 30 = ? (voir ci-dessous)
    };

    [Theory]
    [InlineData(250, 0, 5, 5, 5, null, 0, AtmStatus.InvalidAmount)]
    [InlineData(250, 0, 5, 5, 5, null, -10, AtmStatus.InvalidAmount)]
    [InlineData(250, 0, 5, 5, 5, null, 5, AtmStatus.InvalidAmount)]
